  public static void Run(){api=typeof(Engine).Assembly.GetType("PZ3D.SafehouseCatalog");Check(api!=null,"native safehouse catalog exists");string root=Path.Combine(LauncherTestPaths.Root,"ozl-safehouse-catalog-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var e=new Engine(Path.Combine(root,"Game"),Path.Combine(root,"User"),Path.Combine(root,"Data"),true);string meta=Path.Combine(e.User,"Saves","Sandbox","Source","map_meta.bin");byte[] raw=Fixture(249,2);Put(meta,raw);object result=List(e,"Sandbox/Source");Array rows=F<Array>(result,"houses");Check(F<bool>(result,"detected")&&F<bool>(result,"readable")&&!F<bool>(result,"manualFallback")&&F<string>(result,"state")=="detected"&&F<int>(result,"worldVersion")==249&&rows.Length==2,"world249 discovers saved claims after exact variable-size cell records");object first=rows.GetValue(0),bounds=F<object>(first,"bounds");Check(F<string>(first,"name")=="湖边避难所"&&F<string>(first,"title")=="湖边避难所"&&F<string>(first,"owner")=="张三"&&F<string[]>(first,"members").SequenceEqual(new[]{"小明","Jane"})&&F<string>(first,"location")=="河岸","strict UTF8 records preserve title owner members and location");Check(F<int>(first,"x")==720&&F<int>(first,"y")==-16&&F<int>(first,"width")==17&&F<int>(first,"height")==9&&F<int>(bounds,"minX")==720&&F<int>(bounds,"minY")==-16&&F<int>(bounds,"maxX")==736&&F<int>(bounds,"maxY")==-8,"bounds use the saved rectangle with inclusive maximum and negative coordinates");Check(F<string>(rows.GetValue(1),"name").Length>0,"untitled claim receives a display label without invented coordinates");string id=F<string>(first,"id"),stamp=F<string>(result,"stamp");Check(stamp.Length==64&&id==F<string>(F<Array>(List(e,"Sandbox/Source"),"houses").GetValue(0),"id"),"house IDs are stable for the exact metadata snapshot");Check(raw.SequenceEqual(File.ReadAllBytes(meta))&&!Directory.Exists(e.Data)&&Directory.GetFiles(Path.GetDirectoryName(meta)).Length==1,"catalog reads never write game metadata user settings or application state");
   Check(api.GetMethod("Resolve")!=null,"native automatic selection resolution exists");object resolved=Resolve(e,"Sandbox/Source",stamp,id);Check(F<int>(resolved,"minX")==720&&F<int>(resolved,"maxX")==736&&F<int>(resolved,"minY")==-16&&F<int>(resolved,"maxY")==-8,"automatic selection freshly resolves the exact native rectangle");Refuses(()=>Resolve(e,"Sandbox/Source",stamp,new string('0',32)),"unknown automatic house identity cannot authorize submitted coordinates");Put(Path.Combine(e.User,"Saves","Sandbox","Other","map_meta.bin"),raw);Refuses(()=>Resolve(e,"Sandbox/Other",stamp,id),"automatic house identity is bound to the selected source save even for identical metadata bytes");
