   Put(meta,Fixture(247));result=List(e,"Sandbox/Source");Check(F<bool>(result,"detected")&&F<int>(result,"worldVersion")==247&&F<int>(F<object>(F<Array>(result,"houses").GetValue(0),"bounds"),"maxX")==736,"verified world247 has the same saved claim structure and remains catalog-readable");Check(F<string>(result,"stamp")!=stamp&&F<string>(F<Array>(result,"houses").GetValue(0),"id")!=id,"metadata changes invalidate the opaque house selection identity");Refuses(()=>Resolve(e,"Sandbox/Source",stamp,id),"changed metadata refuses a stale automatic selection before preview or apply");Refuses(()=>SelectionLease(e,"Sandbox/Source",stamp,id),"selection lease freshly rejects a stale map metadata stamp");Put(meta,Fixture(247));
   Put(meta,Fixture(249,0));result=List(e,"Sandbox/Source");Check(!F<bool>(result,"detected")&&F<bool>(result,"readable")&&F<bool>(result,"manualFallback")&&F<Array>(result,"houses").Length==0&&F<string>(result,"state")=="none"&&F<string>(result,"message").Contains("手动"),"ordinary singleplayer with no claim offers manual fallback without a guessed house");Refuses(()=>Resolve(e,"Sandbox/Source",F<string>(result,"stamp"),id),"manual fallback without real claims cannot be resolved as an automatic house");File.Delete(meta);result=List(e,"Sandbox/Source");Check(F<string>(result,"state")=="missing"&&!F<bool>(result,"readable")&&F<bool>(result,"manualFallback")&&F<Array>(result,"houses").Length==0,"missing metadata offers an explicit manual fallback");
   foreach(byte[] invalid in new[]{Fixture().Take(22).ToArray(),Fixture().Take(150).ToArray(),Fixture(width:0),Fixture(width:-1),Fixture(width:100,x:int.MaxValue-5),Fixture(badUtf:true),new byte[32]}){Put(meta,invalid);result=List(e,"Sandbox/Source");Check(!F<bool>(result,"readable")&&!F<bool>(result,"detected")&&F<bool>(result,"manualFallback")&&F<Array>(result,"houses").Length==0&&F<string>(result,"state")=="unreadable","corrupt or invalid saved bounds fail the whole catalog without partial guessed selections");}
